/// <summary>
/// PricingAttribute of table <c>CustTable</c> field MultiLineDisc.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, MultiLineDisc))]
internal class GUPPricingAttributeCustTableMultiLineDisc extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, MultiLineDisc);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    Custtable       custTable;
    PriceDiscGroup  priceDiscGroup;

    while select MultiLineDisc from custtable
        group by MultiLineDisc
        join priceDiscGroup
        group by GroupId, Name, Module, Type
        where custTable.MultiLineDisc == priceDiscGroup.GroupId && priceDiscGroup.Module  == ModuleInventCustVend::Cust &&
            priceDiscGroup.Type == PriceGroupType::MultiLineDiscGroup
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(priceDiscGroup.GroupId, priceDiscGroup.Name);
        ret.add(valueObject);
    }
    return ret;
}
